create table audit_events (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, action varchar(40) not null check (action in ('REGISTER','LOGIN_SUCCESS','LOGIN_FAILURE','ADMIN_CREATED','USER_DISABLED')), ip varchar(45), actor varchar(100) not null, target varchar(100), detail varchar(500), primary key (id));
create table button_events (button_code integer, distance_km float(53), found_count integer, press_count integer, success boolean, client_time timestamp(6) with time zone, id bigint generated by default as identity, received_at timestamp(6) with time zone not null, app_version varchar(32), device_id varchar(64) not null, driver_id varchar(64), primary key (id));
create table device (first_seen timestamp(6) with time zone, id bigint generated by default as identity, last_seen timestamp(6) with time zone, app_version varchar(255), device_id varchar(255) not null unique, model varchar(255), primary key (id));
create table error_events (err_count integer, latency_ms integer, id bigint generated by default as identity, received_at timestamp(6) with time zone not null, app_version varchar(32), device_id varchar(64) not null, error_type varchar(64), primary key (id));
create table event_log (has_error boolean not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, latency_ms bigint, occurred_at timestamp(6) with time zone, error_message varchar(2000), category varchar(255), device_id varchar(255) not null, primary key (id));
create table heartbeats (active_now boolean, ble_connected boolean, driver_enabled boolean, client_time timestamp(6) with time zone, id bigint generated by default as identity, received_at timestamp(6) with time zone not null, app_version varchar(32), device_id varchar(64) not null, driver_id varchar(64), ble_device_id varchar(128), primary key (id));
create table message_classifications (is_important boolean, id bigint generated by default as identity, received_at timestamp(6) with time zone not null, category varchar(32), device_id varchar(64) not null, primary key (id));
create table roles (id bigint generated by default as identity, name varchar(20) not null unique check (name in ('SUPER_ADMIN','ADMIN','DRIVER')), primary key (id));
create table sos_events (contacts_sent integer, contacts_total integer, success boolean, id bigint generated by default as identity, received_at timestamp(6) with time zone not null, triggered_at timestamp(6) with time zone, app_version varchar(32), device_id varchar(64) not null, driver_id varchar(64), primary key (id));
create table trip_channel_stats (composed_count integer not null, suggestion_empty_count integer not null, suggestion_used_count integer not null, total_incoming_messages integer not null, id bigint generated by default as identity, trip_id varchar(64) not null, channel varchar(255), primary key (id));
create table trips (avg_processing_ms integer, clarify_retry_count integer not null, composed_count integer not null, counts_consistent boolean, declined_listen_count integer not null, duration_minutes integer, replied_count integer not null, suggestion_empty_count integer not null, suggestion_used_count integer not null, summary_fallback_count integer not null, summary_guardrail_blocked_count integer not null, summary_success_count integer not null, total_incoming_messages integer not null, ended_at timestamp(6) with time zone, received_at timestamp(6) with time zone not null, started_at timestamp(6) with time zone, device_id varchar(64) not null, trip_id varchar(64) not null, app_version varchar(255), driver_id varchar(255), primary key (trip_id));
create table users (enabled boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, role_id bigint not null, username varchar(100) not null unique, password varchar(255) not null, primary key (id));
create index ix_audit_actor on audit_events (actor);
create index ix_audit_created on audit_events (created_at);
create index ix_btn_device on button_events (device_id);
create index ix_btn_code on button_events (button_code);
create index ix_err_type on error_events (error_type);
create index ix_event_device_id on event_log (device_id);
create index ix_event_occurred_at on event_log (occurred_at);
create index ix_hb_device on heartbeats (device_id);
create index ix_hb_received on heartbeats (received_at);
create index ix_cls_cat on message_classifications (category);
create index ix_sos_received on sos_events (received_at);
create index ix_sos_device on sos_events (device_id);
create index ix_trip_device on trips (device_id);
alter table if exists trip_channel_stats add constraint FKh0l5q4cait493831up7h7ph3j foreign key (trip_id) references trips;
alter table if exists users add constraint FKp56c1712k691lhsyewcssf40f foreign key (role_id) references roles;
